import * as THREE from 'three';
// import { TextureLoader, SRGBColorSpace } from 'three';

import { WebGLRenderer } from 'three';
import { WebGPURenderer } from 'three/webgpu';

import config from '../utils/config';

import { RendererWrapper } from './Wrapper/RendererWrapper';
import { CameraWrapper } from './Wrapper/CameraWrapper';
import { EventWrapper } from './Wrapper/EventWrapper';
import { LightWrapper } from './Wrapper/LightWrapper';
import { PostProcessingWrapper } from './Wrapper/PostProcessingWrapper';

import { CLICK_TYPE } from '../utils/const';

export class RendererCore {
	public upVector: THREE.Vector3;
	public host: HTMLElement;

	public rendererWrapper: RendererWrapper;
	public scene: THREE.Scene;
	public renderer: WebGLRenderer | WebGPURenderer;

	public cameraWrapper: CameraWrapper;
	public lightWrapper: LightWrapper;
	public eventWrapper: EventWrapper;
	public postProcessingWrapper: PostProcessingWrapper | undefined = undefined;

	public useWebGPU: boolean = false;
	public needsRender = true;
	public isPerformanceMode = true;
	public animation: boolean = true;
	public debuggerMode = false;

	public ready = false;

	private _id: string = '';

	constructor(id: string, isPerformanceMode = false) {
		this._id = id;
		this.isPerformanceMode = isPerformanceMode;
		this.upVector = new THREE.Vector3(config.upVector[0], config.upVector[1], config.upVector[2]);
		this.host = document.getElementById(id);
		console.log(this.host);
	}
	public async init() {
		this.rendererWrapper = new RendererWrapper(this);
		await this.rendererWrapper.init();

		this.lightWrapper = new LightWrapper(this);
		await this.lightWrapper.init();

		this.cameraWrapper = new CameraWrapper(this);
		this.eventWrapper = new EventWrapper(this);

		if (true) {
			this.postProcessingWrapper = new PostProcessingWrapper(this);
			await this.postProcessingWrapper.init();
		}

		this.eventBind();
		this.rendererWrapper.loop();
	}

	public updateHDRI(name: string) {
		this.lightWrapper.updateHDRI(name);
	}
	public updateSolarVec(x: number, y: number, z: number) {
		this.lightWrapper.updateDirectionalLightVec(x, z, -y);
	}
	public cameraStaring() {
		this.cameraWrapper.cameraStaring();
	}
	private eventBind() {
		this.eventWrapper.InitNativeMouseEvent(this.renderer.domElement);
	}
	public toggleEffect(value: boolean | undefined = undefined) {
		this.postProcessingWrapper.toggleEffect(value);
	}

	public toggleAnimationRotatingA() {
		this.cameraWrapper.animationRotationA = !this.cameraWrapper.animationRotationA;
	}
	public toggleAnimationRotatingB() {
		this.cameraWrapper.animationRotationB = !this.cameraWrapper.animationRotationB;
	}
	public toggleHDRIBackground(value: boolean) {
		this.lightWrapper.toggleHDRIBackground(value);
	}
	public renderForce() {
		this.rendererWrapper.renderForce();
	}
	public toggleAdaptiveRendering() {
		this.rendererWrapper.toggleAdaptiveRendering();
	}
	public onMouseEventListener = (e: MouseEvent, type: CLICK_TYPE) => {};
	public update() {
		return false;
	}
	public readyBinding = () => {
		return false;
	};
	public destroy() {
		this.rendererWrapper.disposeScene();

		while (this.host.lastChild) {
			this.host.removeChild(this.host.lastChild);
		}
	}
}
