import { EnvironmentType } from '../../';
import { AppCommon } from './';
export class APIHypercube {
	public common: AppCommon;
	constructor(common: AppCommon) {
		this.common = common;
	}
	public shiftEnvironmentType(type: EnvironmentType) {
		this.common.hideAll();
		switch (type) {
			case EnvironmentType.Substation:
				this.common.showSubstation();
				break;

			case EnvironmentType.SubstationDiorama:
				this.common.showSubstationDiorama();
				break;

			default:
				this.common.showStudioEnv();
				break;
		}
	}
}
